fn decode_request(r: &mut Reader) -> Result<Request, Refusal> {
    if r.at() != b'{' {
        return r.refuse("wrong_type");
    }
    r.enter()?;
    r.pos += 1;
    let mut field_profile: Option<String> = None;
    let mut field_image: Option<ImageRequest> = None;
    let mut field_duration_ms: i64 = Default::default();
    let mut seen: u32 = 0;
    r.skip_ws();
    if r.at() != b'}' {
        loop {
            r.skip_ws();
            if r.at() != b'"' {
                return r.refuse("malformed");
            }
            let key = r.string()?;
            r.skip_ws();
            if r.at() != b':' {
                return r.refuse("malformed");
            }
            r.pos += 1;
            r.skip_ws();
            match key.as_str() {
                "profile" => {
                    if seen & 1 != 0 {
                        return r.refuse("duplicate_field");
                    }
                    seen |= 1;
                    field_profile = Some(r.string()?);
                }
                "image" => {
                    if seen & 2 != 0 {
                        return r.refuse("duplicate_field");
                    }
                    seen |= 2;
                    field_image = Some(decode_image_request(r)?);
                }
                "duration_ms" => {
                    if seen & 4 != 0 {
                        return r.refuse("duplicate_field");
                    }
                    seen |= 4;
                    field_duration_ms = r.integer(i64::MIN, i64::MAX)?;
                }
                _ => {
                    return r.refuse("unknown_field");
                }
            }
            r.skip_ws();
            if r.at() != b',' {
                break;
            }
            r.pos += 1;
        }
    }
    if r.at() != b'}' {
        return r.refuse("malformed");
    }
    r.pos += 1;
    r.depth -= 1;
    if seen & 3 != 3 {
        return r.refuse("missing_field");
    }
    let Some(field_image) = field_image else {
        return r.refuse("missing_field");
    };
    let Some(field_profile) = field_profile.as_deref().and_then(Profile::from_wire) else {
        return r.refuse("bad_enum");
    };
    Ok(Request {
        profile: field_profile,
        image: field_image,
        duration_ms: field_duration_ms,
    })
}

